    <div class="market-summary"><p><strong><?= count($marketItems) ?></strong><?= $e($tr(' products in this collection',' produktów w tej kolekcji')) ?></p><span><?= $e($tr('Clear licence terms. Transparent release status.','Jasne warunki licencji. Przejrzysty status wydań.')) ?></span></div>
