        <div class="market-filter-footer"><div class="market-chips" role="group" aria-label="<?= $e($tr('Quick pricing filters','Szybkie filtry ceny')) ?>"><?php foreach (['all'=>$tr('All prices','Wszystkie ceny'),'free'=>$tr('Free','Bezpłatne'),'paid'=>$tr('Paid','Płatne')] as $key=>$label): ?><button type="button" data-market-price="<?= $key ?>" aria-pressed="<?= $key==='all'?'true':'false' ?>"><?= $label ?></button><?php endforeach; ?></div><p role="status" aria-live="polite" aria-atomic="true" data-market-count><?= count($marketItems) ?> <?= $e($tr('results','wyników')) ?></p><button class="market-reset" type="reset"><?= $e($tr('Reset filters','Wyczyść filtry')) ?></button></div>
