    <?php foreach ($marketItems as $item): ?>
        <article class="market-card" data-market-item data-product="<?= $e($item['product']) ?>" data-category="<?= $item['type'] ?>" data-pricing="<?= $item['pricing'] ?>">
            <div class="market-card-top"><span class="market-icon" aria-hidden="true"><svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="<?= $marketIcons[$item['type']] ?>"/></svg></span><span class="market-type"><?= $marketTypes[$item['type']] ?></span></div>
            <h2><a data-market-open href="<?= $e($item['url']) ?>"><?= $e($item['title']) ?></a></h2>
            <p class="market-description"><?= $e($item['description']) ?></p>
            <div class="market-meta"><span class="market-price <?= $item['pricing']==='free'?'is-free':'' ?>"><?= $e($item['price']) ?></span><span class="market-license"><?= $e($item['pricing']==='free'?$tr('CMS licence required','Wymagana licencja CMS'):($item['type']==='system'?$tr('System licence','Licencja systemu'):$tr('Separate licence','Osobna licencja'))) ?></span></div>
            <p class="market-availability"><?= $e($item['status']) ?></p>
            <div class="market-actions"><a class="market-action" data-market-open href="<?= $e($item['url']) ?>" aria-label="<?= $e($tr('View details','Zobacz szczegóły') . ': '. $item['title']) ?>"><?= $e($tr('View details','Zobacz szczegóły')) ?> <span aria-hidden="true">＋</span></a><button class="market-action market-status-action" type="button" data-market-status hidden aria-label="<?= $e($tr('Download status','Status pobierania') . ': '. $item['title']) ?>"><?= $e($tr('Download status','Status pobierania')) ?> <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M5 11h14v10H5zM8 11V7a4 4 0 0 1 8 0v4m-4 4v3"/></svg></button></div>
        </article>
    <?php endforeach; ?>
    </div>
    <div class="market-empty" data-market-empty hidden><h2><?= $e($tr('No matching packages','Brak pasujących pakietów')) ?></h2><p><?= $e($tr('Try a different search or reset the filters to see this collection.','Zmień wyszukiwanie lub wyczyść filtry, aby zobaczyć tę kolekcję.')) ?></p></div>
